"""
RESILIENT TRAFFIC GUARDIAN — Command Center Dashboard
--------------------------------------------------------
Built for a traffic control officer / department head, not a developer —
so the top of the screen always shows ONE clear status, and technical
detail is available but tucked away for those who want to dig into it.

Run with:
    streamlit run dashboard.py

If you have the Arduino plugged in, set ARDUINO_PORT below to your port
(e.g. "COM5" on Windows, "/dev/ttyUSB0" or "/dev/cu.usbmodemXXXX" on
Mac/Linux). Leave it as None to run in pure-software simulated mode.
"""

import time
import datetime
import streamlit as st
import pandas as pd

from traffic_guardian_core import ResilientTrafficGuardian

ARDUINO_PORT = None  # <-- set this to your Arduino's serial port when ready

# Your traffic-light photo, embedded directly as base64 so this single
# file is fully self-contained -- no separate image file needed at all.
BACKGROUND_IMAGE_B64 = ""

st.set_page_config(page_title="Traffic Guardian — Command Center", page_icon="🛡️", layout="wide", initial_sidebar_state="expanded")

# ---------- SESSION STATE ----------
if "guardian" not in st.session_state:
    st.session_state.guardian = ResilientTrafficGuardian(arduino_port=ARDUINO_PORT)
if "live" not in st.session_state:
    st.session_state.live = True   # ON by default — numbers keep updating without manual toggling
if "alert_log" not in st.session_state:
    st.session_state.alert_log = []   # notification feed: breach detected / resolved
if "last_mode" not in st.session_state:
    st.session_state.last_mode = "NORMAL"

guardian = st.session_state.guardian

# =====================================================================
# BACKGROUND PHOTO — your image, shown at 95% visibility across the
# whole app (a light 15% dark overlay is blended in just to keep text
# readable without dulling the photo much).
# =====================================================================
st.markdown(
    f"""
    <style>
    #MainMenu, footer {{visibility: hidden;}}
    header {{background: transparent;}}
    .stApp {{
        background-image: linear-gradient(rgba(5,7,10,0.65), rgba(5,7,10,0.65)),
                           url("data:image/jpeg;base64,{BACKGROUND_IMAGE_B64}");
        background-size: cover;
        background-position: center;
        background-repeat: no-repeat;
        background-attachment: fixed;
    }}
    </style>
    """,
    unsafe_allow_html=True,
)

# ---------- HEADER ----------
st.markdown(
    """
    <div style="text-align:center; font-family:'Georgia','Times New Roman',serif; margin-bottom:10px;
                padding:14px; border-radius:10px;
                background:linear-gradient(180deg, rgba(0,0,0,0.35) 0%, rgba(0,0,0,0.1) 100%);">
        <div style="font-size:42px; font-weight:700; color:white; text-shadow:0 2px 10px rgba(0,0,0,0.8);">🛡️ Resilient Traffic Guardian</div>
        <div style="font-size:16px; font-style:italic; color:#eee; margin-top:4px; text-shadow:0 1px 6px rgba(0,0,0,0.8);">
            "Cyber-Physical Defense for Adaptive Traffic Signals"
        </div>
    </div>
    """,
    unsafe_allow_html=True,
)

# ---------- SIDEBAR: TEST SCENARIOS ----------
st.sidebar.header("🧪 Test Scenarios")
st.sidebar.caption("Simulates a realistic failure or attack so you can see how "
                    "the system responds. No real system is affected.")

if st.sidebar.button("✅ Normal Operation", width='stretch'):
    guardian.clear_attack()

if st.sidebar.button("📷 Camera Feed Compromised", width='stretch'):
    guardian.trigger_attack("camera_spoof")

if st.sidebar.button("🖥️ Unsafe Command from Central", width='stretch'):
    guardian.trigger_attack("malicious_command")

if st.sidebar.button("🔌 Central System Offline", width='stretch'):
    guardian.trigger_attack("server_down")

st.sidebar.divider()
st.session_state.live = st.sidebar.toggle("▶️ Live monitoring", value=st.session_state.live)
refresh_rate = st.sidebar.slider("Refresh interval (seconds)", 0.5, 3.0, 1.0, 0.5)
manual_tick = st.sidebar.button("⏭️ Advance one step (manual)", width='stretch')

# ---------- RUN ONE TICK ----------
if st.session_state.live or manual_tick:
    result = guardian.tick()
else:
    result = guardian.history[-1] if guardian.history else guardian.tick()


def _breach_reason(r):
    if r.mode == "SAFE_MODE":
        return "Central control link lost — intersection switched to local safe mode."
    if not r.safety_check.ok:
        return f"Unsafe command rejected — {r.safety_check.reason}"
    if not r.sensor_check.ok:
        label = {"camera": "Camera", "sensor": "Road sensor"}
        bypassed = label.get(r.sensor_check.bypassed_source, "A sensor")
        return f"{bypassed} data bypassed — {r.sensor_check.reason}"
    return "Anomaly detected."


# ---------- BREACH DETECTION -> ACTIVE ALERTING ----------
# Fires the instant the system transitions INTO or OUT OF a breach state,
# rather than just showing a static banner — this is what makes it an
# alerting system rather than a passive dashboard.
if result.mode != "NORMAL" and st.session_state.last_mode == "NORMAL":
    reason = _breach_reason(result)
    ts = datetime.datetime.now().strftime("%H:%M:%S")
    st.session_state.alert_log.insert(0, {
        "time": ts, "type": "BREACH", "mode": result.mode, "reason": reason,
    })
    st.toast(f"🚨 Breach detected: {reason}", icon="🚨")
elif result.mode == "NORMAL" and st.session_state.last_mode != "NORMAL":
    ts = datetime.datetime.now().strftime("%H:%M:%S")
    st.session_state.alert_log.insert(0, {
        "time": ts, "type": "RESOLVED", "mode": "NORMAL",
        "reason": "System returned to normal operation.",
    })
    st.toast("✅ Situation resolved — system back to normal.", icon="✅")

st.session_state.last_mode = result.mode
st.session_state.alert_log = st.session_state.alert_log[:20]

# =====================================================================
# TOP STATUS BANNER — the one thing an officer needs to see instantly
# =====================================================================
BANNER = {
    "NORMAL":    ("#1e7d34", "✅  ALL SYSTEMS NORMAL",
                  "Signal timing is being adjusted automatically based on verified traffic data."),
    "DEGRADED":  ("#a06a00", "⚠️  ANOMALY DETECTED — MONITORING CLOSELY",
                  "The system has flagged an inconsistency and is protecting the intersection while it investigates."),
    "SAFE_MODE": ("#8f1f1f", "🚨  SAFE MODE ACTIVE — INTERSECTION PROTECTED",
                  "Central connection lost. The intersection is running on a pre-approved fixed timing and remains safe."),
}
color, headline, subtext = BANNER.get(result.mode, BANNER["NORMAL"])

st.markdown(
    f"""
    <div style="background-color:{color}; padding:18px 24px; border-radius:10px; margin-bottom:18px;">
        <div style="font-size:26px; font-weight:700; color:white;">{headline}</div>
        <div style="font-size:15px; color:rgba(255,255,255,0.9); margin-top:4px;">{subtext}</div>
    </div>
    """,
    unsafe_allow_html=True,
)

# =====================================================================
# ALERTS FEED — the notification log an officer actually needs
# =====================================================================
st.subheader("🔔 Recent Alerts")

if not st.session_state.alert_log:
    st.caption("No alerts yet. This feed fills the instant a breach is detected.")
else:
    for entry in st.session_state.alert_log[:5]:
        if entry["type"] == "BREACH":
            st.error(f"**{entry['time']}** — {entry['reason']}  \n"
                     f"📩 *Alert sent to Traffic Control Officer (simulated SMS/email).*")
        else:
            st.success(f"**{entry['time']}** — {entry['reason']}")
    if len(st.session_state.alert_log) > 5:
        with st.expander(f"View all {len(st.session_state.alert_log)} alerts"):
            for entry in st.session_state.alert_log:
                icon = "🚨" if entry["type"] == "BREACH" else "✅"
                st.write(f"{icon} **{entry['time']}** — {entry['reason']}")

st.divider()

# =====================================================================
# WHAT EACH SENSOR CURRENTLY REPORTS — simple metric readout
# =====================================================================
st.subheader("What each sensor currently reports")

sc1, sc2, sc3 = st.columns(3)
sc1.metric("📷 Camera count", result.camera_count)
sc2.metric("📡 Road sensor count", result.sensor_count)
sc3.metric("📊 Expected baseline", result.baseline)

if not result.sensor_check.ok:
    bypassed = result.sensor_check.bypassed_source
    trusted = result.sensor_check.trusted_source
    label = {"camera": "📷 Camera", "sensor": "📡 Road sensor"}
    st.error(
        f"⛔ **{label[bypassed]} data has been bypassed** — its reading doesn't match "
        f"the other source and is being excluded from the signal-timing decision. "
        f"The system is relying on **{label[trusted]}** instead."
    )
else:
    st.success("✅ Both sources agree — camera and road sensor data verified.")

st.divider()

# =====================================================================
# INTERSECTION STATUS — the physical picture
# =====================================================================
st.subheader("Intersection Status")
st.caption(f"🔄 Live — updating every {refresh_rate:.1f}s")

LIGHT_EMOJI = {"red": "🔴", "yellow": "🟡", "green": "🟢"}

def render_light(label, color):
    st.markdown(f"**{label}**")
    for c in ["red", "yellow", "green"]:
        st.markdown(f"{LIGHT_EMOJI[c] if c == color else '⚪'}")

ic1, ic2, ic3 = st.columns([1, 1, 2])
with ic1:
    render_light("⬆️⬇️ Main Street (N–S)", result.road_a_color)
    if result.road_a_color == "green":
        st.caption(f"⏱️ {result.seconds_remaining}s remaining")
with ic2:
    render_light("⬅️➡️ Cross Street (E–W)", result.road_b_color)
    if result.road_b_color == "green":
        st.caption(f"⏱️ {result.seconds_remaining}s remaining")
with ic3:
    st.metric("Confidence in current data", f"{result.trust_score}%")
    st.progress(result.trust_score / 100)

st.markdown("**Why the signal is timed this way**")
comp1, comp2 = st.columns(2)
main_count = max(result.camera_count, result.sensor_count) if not result.sensor_check.ok else result.sensor_count
with comp1:
    st.markdown(f"Main Street: **{main_count} vehicles** → **{result.green_a_applied}s** green")
    st.progress(min(1.0, result.green_a_applied / 45))
with comp2:
    st.markdown(f"Cross Street: **{result.road_b_count} vehicles** → **{result.green_b_applied}s** green")
    st.progress(min(1.0, result.green_b_applied / 45))
st.caption(result.signal_decision_reason)

st.divider()

# =====================================================================
# RECOMMENDED ACTION / SYSTEM RESPONSE — decision-support summary
# =====================================================================
st.subheader("System Response")

if result.mode == "SAFE_MODE":
    st.error(
        "**Action taken:** Central control link is down. The intersection controller "
        "has switched to a **safe, fixed timing** on its own — it does not need the "
        "central system to keep functioning safely. No manual action is required; "
        "traffic continues to flow."
    )
elif not result.safety_check.ok:
    st.warning(
        f"**Action taken:** A signal-timing command outside the safe range was "
        f"received and **rejected automatically**. {result.safety_check.reason} "
        f"The intersection continues on the safe adjusted timing."
    )
elif not result.sensor_check.ok:
    st.warning(
        f"**Action taken:** Camera and sensor data disagree. The system is trusting "
        f"the more plausible reading and continuing to operate normally. "
        f"Recommend dispatching a technician to inspect the camera if this persists."
    )
elif not result.behavior_check.ok:
    st.info(
        f"**Note:** Traffic volume looks unusual for this time of day "
        f"({result.behavior_check.reason}) The system is continuing to monitor; "
        f"no unsafe condition has been detected."
    )
else:
    st.success("**No action needed.** All checks passed — signal timing is being "
               "adjusted normally based on verified, cross-checked data.")

st.divider()

# =====================================================================
# TECHNICAL DETAIL — tucked away for anyone who wants to dig in
# =====================================================================
with st.expander("🔧 Technical detail (for engineers / judges' Q&A)"):
    st.markdown("**Layer 1 — Sensor Cross-Check**")
    (st.success if result.sensor_check.ok else st.error)(result.sensor_check.reason)

    st.markdown("**Layer 2 — Behavioural Baseline**")
    (st.success if result.behavior_check.ok else st.error)(result.behavior_check.reason)

    st.markdown("**Layer 3 — Command Safety**")
    (st.success if result.safety_check.ok else st.error)(result.safety_check.reason)

    st.markdown("**Edge controller (Arduino) response**")
    st.code(str(result.arduino_response))

    st.markdown("**Trust score formula**")
    st.caption("40% sensor agreement + 30% historical consistency + 30% command safety")

    st.markdown("**Event log (last 15 readings)**")
    rows = []
    for r in guardian.history[-15:][::-1]:
        rows.append({
            "Mode": r.mode,
            "Camera": r.camera_count,
            "Sensor": r.sensor_count,
            "Confidence %": r.trust_score,
            "Note": r.sensor_check.reason if not r.sensor_check.ok else
                    (r.behavior_check.reason if not r.behavior_check.ok else
                     (r.safety_check.reason if not r.safety_check.ok else "All checks passed")),
        })
    st.dataframe(pd.DataFrame(rows), width='stretch', hide_index=True)

# ---------- LIVE LOOP ----------
if st.session_state.live:
    time.sleep(refresh_rate)
    st.rerun()
